54	func (d *DB) ListMemos(ctx context.Context, find *store.FindMemo) ([]*store.Memo, error) {
55		where, args := []string{"1 = 1"}, []any{}
56	
57		engine, err := filter.DefaultEngine()
58		if err != nil {
59			return nil, err
60		}
61		if err := filter.AppendConditions(ctx, engine, find.Filters, filter.DialectSQLite, &where, &args); err != nil {
62			return nil, err
63		}
64		if v := find.ID; v != nil {
65			where, args = append(where, "`memo`.`id` = ?"), append(args, *v)
66		}
67		if len(find.IDList) > 0 {
68			placeholders := make([]string, 0, len(find.IDList))
69			for range find.IDList {
70				placeholders = append(placeholders, "?")
71			}
72			where = append(where, "`memo`.`id` IN ("+strings.Join(placeholders, ",")+")")
73			for _, id := range find.IDList {
74				args = append(args, id)
75			}
76		}
77		if v := find.UID; v != nil {
78			where, args = append(where, "`memo`.`uid` = ?"), append(args, *v)
79		}
80		if len(find.UIDList) > 0 {
81			placeholders := make([]string, 0, len(find.UIDList))
82			for range find.UIDList {
83				placeholders = append(placeholders, "?")
84			}
85			where = append(where, "`memo`.`uid` IN ("+strings.Join(placeholders, ",")+")")
86			for _, uid := range find.UIDList {
87				args = append(args, uid)
88			}
89		}
90		if v := find.CreatorID; v != nil {
91			where, args = append(where, "`memo`.`creator_id` = ?"), append(args, *v)
92		}
93		if v := find.RowStatus; v != nil {
94			where, args = append(where, "`memo`.`row_status` = ?"), append(args, *v)
95		}
96		if v := find.VisibilityList; len(v) != 0 {
97			placeholder := []string{}
98			for _, visibility := range v {
99				placeholder = append(placeholder, "?")
100				args = append(args, visibility.String())
101			}
102			where = append(where, fmt.Sprintf("`memo`.`visibility` IN (%s)", strings.Join(placeholder, ",")))
103		}
104		if find.ExcludeComments {
105			where = append(where, "`parent_uid` IS NULL")
106		}
107	
108		order := "DESC"
109		if find.OrderByTimeAsc {
110			order = "ASC"
111		}
112		orderBy := []string{}
113		if find.OrderByPinned {
114			orderBy = append(orderBy, "`pinned` DESC")
115		}
116		if find.OrderByUpdatedTs {
117			orderBy = append(orderBy, "`updated_ts` "+order)
118		} else {
119			orderBy = append(orderBy, "`created_ts` "+order)
120		}
121		// Add id as final tie-breaker
122		orderBy = append(orderBy, "`id` DESC")
123		fields := []string{
124			"`memo`.`id` AS `id`",
125			"`memo`.`uid` AS `uid`",
126			"`memo`.`creator_id` AS `creator_id`",
127			"`memo`.`created_ts` AS `created_ts`",
128			"`memo`.`updated_ts` AS `updated_ts`",
129			"`memo`.`row_status` AS `row_status`",
130			"`memo`.`visibility` AS `visibility`",
131			"`memo`.`pinned` AS `pinned`",
132			"`memo`.`payload` AS `payload`",
133			"CASE WHEN `parent_memo`.`uid` IS NOT NULL THEN `parent_memo`.`uid` ELSE NULL END AS `parent_uid`",
134		}
135		if !find.ExcludeContent {
136			fields = append(fields, "`memo`.`content` AS `content`")
137		}
138	
139		query := "SELECT " + strings.Join(fields, ", ") + "FROM `memo` " +
140			"LEFT JOIN `user` AS `memo_creator` ON `memo`.`creator_id` = `memo_creator`.`id` " +
141			"LEFT JOIN `memo_relation` ON `memo`.`id` = `memo_relation`.`memo_id` AND `memo_relation`.`type` = \"COMMENT\" " +
142			"LEFT JOIN `memo` AS `parent_memo` ON `memo_relation`.`related_memo_id` = `parent_memo`.`id` " +
143			"WHERE " + strings.Join(where, " AND ") + " " +
144			"ORDER BY " + strings.Join(orderBy, ", ")
145		if find.Limit != nil {
146			query = fmt.Sprintf("%s LIMIT %d", query, *find.Limit)
147			if find.Offset != nil {
148				query = fmt.Sprintf("%s OFFSET %d", query, *find.Offset)
149			}
150		}
151	
152		rows, err := d.db.QueryContext(ctx, query, args...)
153		if err != nil {
154			return nil, err
155		}
156		defer rows.Close()
157	
158		list := make([]*store.Memo, 0)
159		for rows.Next() {
160			var memo store.Memo
161			var payloadBytes []byte
162			dests := []any{
163				&memo.ID,
164				&memo.UID,
165				&memo.CreatorID,
166				&memo.CreatedTs,
167				&memo.UpdatedTs,
168				&memo.RowStatus,
169				&memo.Visibility,
170				&memo.Pinned,
171				&payloadBytes,
172				&memo.ParentUID,
173			}
174			if !find.ExcludeContent {
175				dests = append(dests, &memo.Content)
176			}
177			if err := rows.Scan(dests...); err != nil {
178				return nil, err
179			}
180			payload := &storepb.MemoPayload{}
181			if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
182				return nil, errors.Wrap(err, "failed to unmarshal payload")
183			}
184			memo.Payload = payload
185			list = append(list, &memo)
186		}
187	
188		if err := rows.Err(); err != nil {
189			return nil, err
190		}
191	
192		return list, nil
193	}
